import React from 'react';
import userEvent from '@testing-library/user-event';
import { render, screen } from '@testing-library/react';
import { SearchField } from '../..';

describe('SearchField', () => {
  it('should render', () => {
    render(<SearchField.Root data-testid="search-input" />);
    expect(screen.getByTestId('search-input')).toBeInTheDocument();
  });

  it('should render with an external ref being passed', () => {
    const ref = React.createRef();
    render(<SearchField.Root ref={ref} data-testid="search-input" />);
    expect(screen.getByTestId('search-input')).toBeInTheDocument();
  });

  it('should render with a placeholder', () => {
    render(<SearchField.Root placeholder="Placeholder test" />);
    expect(screen.getByPlaceholderText('Placeholder test')).toBeInTheDocument();
  });

  it('should render with a defaultValue', () => {
    render(<SearchField.Root placeholder="Placeholder test" defaultValue="Default Value Test" />);
    expect(screen.getByDisplayValue('Default Value Test')).toBeInTheDocument();
  });

  it('should render as controlled', () => {
    render(<SearchField.Root placeholder="Placeholder test" value="controlled value" />);
    expect(screen.getByDisplayValue('controlled value')).toBeInTheDocument();
  });

  it('should be able to clear the input when click on the clear button', async () => {
    const user = userEvent.setup();
    const { container } = render(<SearchField.Root placeholder="Search test" />);
    const input = screen.getByPlaceholderText('Search test');
    await user.type(input, 'Some search text');
    expect(screen.getByDisplayValue('Some search text')).toBeInTheDocument();
    await user.click(container.querySelector('[aria-label="Clear input"]'));
    expect(screen.queryByDisplayValue('Some search text')).not.toBeInTheDocument();
  });

  it('should be able to render with onClear prop passed and to call it', async () => {
    const user = userEvent.setup();
    const mockOnClear = jest.fn();
    const { container } = render(
      <SearchField.Root onClear={mockOnClear} placeholder="Search test" />
    );
    const input = screen.getByPlaceholderText('Search test');
    await user.type(input, 'Some search text');
    expect(screen.getByDisplayValue('Some search text')).toBeInTheDocument();
    await user.click(container.querySelector('[aria-label="Clear input"]'));
    expect(screen.queryByDisplayValue('Some search text')).not.toBeInTheDocument();
    expect(mockOnClear).toHaveBeenCalled();
  });

  it('should be able to call onChange prop when passed', async () => {
    const user = userEvent.setup();
    const mockOnchange = jest.fn();

    render(<SearchField.Root placeholder="Search test" onChange={mockOnchange} />);

    const input = screen.getByPlaceholderText('Search test');

    await user.type(input, 'Some search text');

    expect(mockOnchange).toHaveBeenCalledTimes(16);
  });

  it('should call onSearch when pressing enter', async () => {
    const user = userEvent.setup();
    const mockOnSearch = jest.fn();

    render(<SearchField.Root placeholder="Search test" onSearch={mockOnSearch} />);
    const input = screen.getByPlaceholderText('Search test');
    await user.type(input, 'Some search text');
    input.focus();
    await user.keyboard('[Enter]');
    expect(mockOnSearch).toHaveBeenCalled();
  });

  it('should render with filter', () => {
    render(
      <SearchField.Root placeholder="Search test" size="large">
        <SearchField.Filter placeholder="Select a value">
          <SearchField.FilterOption value="Option 1">Option 1</SearchField.FilterOption>
          <SearchField.FilterOption value="Option 2">Option 2</SearchField.FilterOption>
          <SearchField.FilterOption value="Option 3">Option 3</SearchField.FilterOption>
        </SearchField.Filter>
      </SearchField.Root>
    );
    const filter = screen.getByText('Select a value');
    expect(filter).toBeInTheDocument();
  });

  it('should focus on input when clicking in the container', async () => {
    const user = userEvent.setup();
    render(<SearchField.Root placeholder="Search placeholder" />);

    const wrapper = screen.getByTestId('search-field-wrapper');

    await user.click(wrapper);
    const input = screen.getByPlaceholderText('Search placeholder');
    expect(document.activeElement).toBe(input);
  });

  it('should throw an error if the element passed as children is not of type filter', async () => {
    expect(() =>
      render(
        <SearchField.Root placeholder="Search placeholder">
          <div>This should throw an error</div>
        </SearchField.Root>
      )
    ).toThrow(
      'Expected the child of SearchField to be a Filter, but received div, please, provide the correct one'
    );
  });
});
